pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target) public {
        // The invariant: after airDrop() is called by a fresh address (with no balance),
        // the target's tokenBalance must never decrease.
        // On the reference, addition is safe and balance always increases or stays same;
        // on the bug, overflow can cause decrease, violating the invariant.

        // We need a caller that satisfies hasNoBalance (balance == 0) and supportsToken.
        // We'll use a fresh EOA address, which has zero balance initially.
        // The supportsToken modifier requires msg.sender to be a Bank contract that returns the correct hash.
        // Since msg.sender is evaluated during the call, we need to make the caller a contract.
        // So we deploy a minimal BankUser contract that acts as a Bank AND calls airDrop.
        // We fuzz the target address whose balance we check.

        // Deploy adversarial helper: a contract that is both the caller (BankUser) and acts as a Bank
        BankUser caller = new BankUser(address(c));

        // Record tokenBalance of target before
        uint256 balBefore = c.tokenBalance(target);

        // Call airDrop via the helper
        caller.triggerAirDrop();

        // Record tokenBalance of target after
        uint256 balAfter = c.tokenBalance(target);

        // Invariant: balance must not decrease
        assertTrue(balAfter >= balBefore, "tokenBalance decreased after airDrop");
    }
}

// Adversarial helper: a contract that acts as a Bank (returns required supportsToken hash)
// and triggers airDrop on behalf of itself.
contract BankUser {
    C public targetContract;
    constructor(address _target) {
        targetContract = C(_target);
    }

    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    function triggerAirDrop() external {
        // This contract calls airDrop on the target C.
        // msg.sender for airDrop will be this contract address.
        targetContract.airDrop();
    }
}

