import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // 1. Restrict to admissible domain: caller must be a contract that supportsToken
        vm.assume(caller.code.length > 0);
        // The caller must be a contract that returns the expected hash from supportsToken()
        // We deploy a minimal helper that implements supportsToken
        vm.assume(!_isPrecompile(caller));

        // 2. Deploy an adversarial helper that acts as the Bank contract
        // This helper is needed because the fuzzed address is an EOA with no code,
        // and we need an external party that returns the correct supportsToken value.
        // Actually, the airdrop requires msg.sender to be a Bank that supportsToken.
        // The modifier supportsToken() calls Bank(msg.sender).supportsToken(),
        // which means the caller MUST be a contract that has supportsToken() returning the right hash.
        // We deploy a helper that does exactly that, and use its address as the pranked caller.
        HelperBank bank = new HelperBank();
        address callerAddress = address(bank);

        // Record balance before
        uint256 balanceBefore = c.tokenBalance(callerAddress);

        // Call airDrop as the helper bank
        vm.prank(callerAddress);
        c.airDrop();

        // 3. Assert: tokenBalance must strictly increase
        uint256 balanceAfter = c.tokenBalance(callerAddress);
        assertTrue(balanceAfter > balanceBefore);
    }

    function _isPrecompile(address addr) internal view returns (bool) {
        return addr == address(1) || addr == address(2) || addr == address(3) || addr == address(4) || addr == address(5) || addr == address(6) || addr == address(7) || addr == address(8) || addr == address(9) || (addr >= address(0x01) && addr <= address(0x09));
    }
}

contract HelperBank {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

