pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Give the actor a non-zero balance to trigger the bug
        vm.prank(actor);
        try c.airDrop() {} catch {}
        uint256 balanceBefore = c.tokenBalance(actor);
        vm.prank(actor);
        try c.airDrop() {} catch {}
        uint256 balanceAfter = c.tokenBalance(actor);
        // The reference contract prevents a second successful airdrop (balance stays 20).
        // The buggy contract allows a second increase, so balanceAfter > 20.
        // The universal rule: if the first airdrop succeeded (balanceBefore == 20),
        // then after another attempt, the balance must not increase further.
        assertTrue(balanceBefore == 0 || balanceAfter == balanceBefore);
    }
}

